class Solution {
    int modPow(int base, int exp, int mod) {
        long long res = 1, b = base;
        while (exp > 0) {
            if (exp & 1) res = (res * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
