public:
    vector<int> concatenatedDivisibility(vector<int>& nums, int k) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        vector<int> pow10(n);
        for (int i = 0; i < n; ++i) {
            pow10[i] = modPow(10, to_string(nums[i]).length(), k);
        }

        map<pair<int, int>, bool> memo;
        auto dfs = [&](auto& self, int mask, int rem) -> bool {
            if (mask == (1 << n) - 1) return rem == 0;
            auto st = make_pair(mask, rem);
            if (memo.count(st)) return memo[st];
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    int nRem = ((long long)rem * pow10[i] + nums[i]) % k;
                    if (self(self, mask | (1 << i), nRem)) return memo[st] = true;
                }
            }
            return memo[st] = false;
        };

        if (!dfs(dfs, 0, 0)) return {};

        vector<int> res;
        int mask = 0, rem = 0;
        for (int step = 0; step < n; ++step) {
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    int nRem = ((long long)rem * pow10[i] + nums[i]) % k;
                    if (dfs(dfs, mask | (1 << i), nRem)) {
                        res.push_back(nums[i]);
                        mask |= (1 << i);
                        rem = nRem;
                        break;
                    }
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] concatenatedDivisibility(int[] nums, int k) {
        int n = nums.length;
        Arrays.sort(nums);
        int[] pow10 = new int[n];
        for (int i = 0; i < n; i++) {
            pow10[i] = modPow(10, String.valueOf(nums[i]).length(), k);
        }

        Map<String, Boolean> memo = new HashMap<>();
        if (!dfs(0, 0, n, nums, pow10, k, memo)) return new int[0];

        int[] res = new int[n];
        int mask = 0, rem = 0;
        for (int step = 0; step < n; step++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nRem = (int) (((long) rem * pow10[i] + nums[i]) % k);
                    if (dfs(mask | (1 << i), nRem, n, nums, pow10, k, memo)) {
                        res[step] = nums[i];
                        mask |= (1 << i);
                        rem = nRem;
                        break;
                    }
                }
            }
        }
        return res;
    }

    private boolean dfs(int mask, int rem, int n, int[] nums, int[] pow10, int k, Map<String, Boolean> memo) {
        if (mask == (1 << n) - 1) return rem == 0;
        String key = mask + "#" + rem;
        if (memo.containsKey(key)) return memo.get(key);
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                int nRem = (int) (((long) rem * pow10[i] + nums[i]) % k);
                if (dfs(mask | (1 << i), nRem, n, nums, pow10, k, memo)) {
                    memo.put(key, true);
                    return true;
                }
            }
        }
        memo.put(key, false);
        return false;
    }

    private int modPow(int base, int exp, int mod) {
        long res = 1, b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return (int) res;
    }
}

var concatenatedDivisibility = function(nums, k) {
    const n = nums.length;
    nums.sort((a, b) => a - b);
    const pow10 = nums.map(x => {
        let res = 1;
        let len = String(x).length;
        while (len--) res = (res * 10) % k;
        return res;
    });

    const memo = new Map();
    const dfs = (mask, rem) => {
        if (mask === (1 << n) - 1) return rem === 0;
        const key = `${mask},${rem}`;
        if (memo.has(key)) return memo.get(key);
        for (let i = 0; i < n; i++) {
            if (!(mask & (1 << i))) {
                const nRem = (rem * pow10[i] + nums[i]) % k;
                if (dfs(mask | (1 << i), nRem)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }
        memo.set(key, false);
        return false;
    };

    if (!dfs(0, 0)) return [];

    const res = [];
    let mask = 0, rem = 0;
    for (let step = 0; step < n; step++) {
        for (let i = 0; i < n; i++) {
            if (!(mask & (1 << i))) {
                const nRem = (rem * pow10[i] + nums[i]) % k;
                if (dfs(mask | (1 << i), nRem)) {
                    res.push(nums[i]);
                    mask |= (1 << i);
                    rem = nRem;
                    break;
                }
            }
        }
    }
    return res;
};
